  (8, 3, 'Continuous 5k', '5 km en continu', '[{"kind":"warmup","seconds":300},{"kind":"run","seconds":1800},{"kind":"cooldown","seconds":300}]'::jsonb, 83)
  ) as v(week, day_in_week, title, title_fr, segments, sort_order)
where p.slug = 'c5k-8'
on conflict (plan_id, week, day_in_week) do update set
