  segments = excluded.segments, sort_order = excluded.sort_order;

-- c10k-10
insert into public.run_plans (slug, title, title_fr, description, description_fr, weeks, goal_distance_m, weeks_meta, sort_order)
values ('c10k-10', '10k in 10 weeks', '10 km en 10 semaines', 'Build from a 5k base to 10k with easy runs, intervals and a weekly long run.', 'D''une base de 5 km au 10 km avec footings, fractionnes et une sortie longue par semaine.', 10, 10000, '[{"week":1,"verse_ref":"1 Corinthiens 9.24","verse_text":"Ne savez-vous pas que ceux qui courent dans le stade courent tous, mais qu''un seul remporte le prix? Courez de maniere a le remporter.","verse_ref_en":"1 Corinthians 9:24","verse_text_en":"Don''t you know that those who run in a race all run, but one receives the prize? Run like that, that you may win.","prayer":"Seigneur, merci pour ce corps que tu m''as donne. Donne-moi de commencer avec humilite et de finir avec joie.","prayer_en":"Lord, thank you for this body you gave me. Help me begin in humility and finish with joy."},{"week":2,"verse_ref":"Hebreux 12.1","verse_text":"Rejetons tout fardeau, et le peche qui nous enveloppe si facilement, et courons avec perseverance dans la carriere qui nous est ouverte.","verse_ref_en":"Hebrews 12:1","verse_text_en":"Let''s lay aside every weight and the sin which so easily entangles us, and let''s run with perseverance the race that is set before us.","prayer":"Pere, quand mon souffle devient court, rappelle-moi que ta force se montre dans ma faiblesse.","prayer_en":"Father, when my breath runs short, remind me that your strength shows in my weakness."},{"week":3,"verse_ref":"Esaie 40.31","verse_text":"Mais ceux qui se confient en l''Eternel renouvellent leur force. Ils courent, et ne se lassent point, ils marchent, et ne se fatiguent point.","verse_ref_en":"Isaiah 40:31","verse_text_en":"But those who wait for Yahweh will renew their strength. They will run, and not be weary. They will walk, and not faint.","prayer":"Jesus, apprends-moi la perseverance: un pas apres l''autre, un jour apres l''autre, pour ta gloire.","prayer_en":"Jesus, teach me perseverance: one step after another, one day after another, for your glory."},{"week":4,"verse_ref":"2 Timothee 4.7","verse_text":"J''ai combattu le bon combat, j''ai acheve la course, j''ai garde la foi.","verse_ref_en":"2 Timothy 4:7","verse_text_en":"I have fought the good fight. I have finished the course. I have kept the faith.","prayer":"Seigneur, je depose ma hate. Donne-moi un coeur paisible et des jambes fideles sur la distance.","prayer_en":"Lord, I lay down my hurry. Give me a peaceful heart and faithful legs for the distance."},{"week":5,"verse_ref":"Philippiens 3.13-14","verse_text":"Oubliant ce qui est en arriere et me portant vers ce qui est en avant, je cours vers le but, pour remporter le prix de la vocation celeste de Dieu en Jesus-Christ.","verse_ref_en":"Philippians 3:13-14","verse_text_en":"Forgetting the things which are behind and stretching forward to the things which are before, I press on toward the goal for the prize of the high calling of God in Christ Jesus.","prayer":"Pere, garde mes yeux fixes sur le but et mon coeur reconnaissant pour chaque foulee.","prayer_en":"Father, keep my eyes fixed on the goal and my heart thankful for every stride."},{"week":6,"verse_ref":"1 Corinthiens 9.24","verse_text":"Ne savez-vous pas que ceux qui courent dans le stade courent tous, mais qu''un seul remporte le prix? Courez de maniere a le remporter.","verse_ref_en":"1 Corinthians 9:24","verse_text_en":"Don''t you know that those who run in a race all run, but one receives the prize? Run like that, that you may win.","prayer":"Seigneur, que cette course soit une priere en mouvement. Je cours pour toi, pas pour les regards.","prayer_en":"Lord, let this run be a prayer in motion. I run for you, not for applause."},{"week":7,"verse_ref":"Hebreux 12.1","verse_text":"Rejetons tout fardeau, et le peche qui nous enveloppe si facilement, et courons avec perseverance dans la carriere qui nous est ouverte.","verse_ref_en":"Hebrews 12:1","verse_text_en":"Let''s lay aside every weight and the sin which so easily entangles us, and let''s run with perseverance the race that is set before us.","prayer":"Jesus, dans l''effort comme dans le repos, forme en moi la discipline qui honore ton nom.","prayer_en":"Jesus, in effort as in rest, form in me the discipline that honors your name."},{"week":8,"verse_ref":"Esaie 40.31","verse_text":"Mais ceux qui se confient en l''Eternel renouvellent leur force. Ils courent, et ne se lassent point, ils marchent, et ne se fatiguent point.","verse_ref_en":"Isaiah 40:31","verse_text_en":"But those who wait for Yahweh will renew their strength. They will run, and not be weary. They will walk, and not faint.","prayer":"Pere, merci de renouveler ma force. Que je marche et ne me fatigue point, que je coure sans me lasser.","prayer_en":"Father, thank you for renewing my strength. May I walk and not faint, run and not grow weary."},{"week":9,"verse_ref":"2 Timothee 4.7","verse_text":"J''ai combattu le bon combat, j''ai acheve la course, j''ai garde la foi.","verse_ref_en":"2 Timothy 4:7","verse_text_en":"I have fought the good fight. I have finished the course. I have kept the faith.","prayer":"Seigneur, la ligne d''arrivee approche. Donne-moi de garder la foi jusqu''au bout.","prayer_en":"Lord, the finish line is near. Help me keep the faith to the very end."},{"week":10,"verse_ref":"Philippiens 3.13-14","verse_text":"Oubliant ce qui est en arriere et me portant vers ce qui est en avant, je cours vers le but, pour remporter le prix de la vocation celeste de Dieu en Jesus-Christ.","verse_ref_en":"Philippians 3:13-14","verse_text_en":"Forgetting the things which are behind and stretching forward to the things which are before, I press on toward the goal for the prize of the high calling of God in Christ Jesus.","prayer":"Pere, aujourd''hui je cours vers le but. Merci pour la vocation celeste qui m''attire en avant.","prayer_en":"Father, today I press on toward the goal. Thank you for the high calling that draws me forward."}]'::jsonb, 2)
on conflict (slug) do update set
  title = excluded.title, title_fr = excluded.title_fr,
  description = excluded.description, description_fr = excluded.description_fr,
  weeks = excluded.weeks, goal_distance_m = excluded.goal_distance_m,
  weeks_meta = excluded.weeks_meta, sort_order = excluded.sort_order;

